class Solution {
public:
    int closestFair(int n) {
        std::string s = std::to_string(n);
        int len = s.size();
        if (len % 2 == 1) {
            int half = (len + 1) / 2;
            std::string res = "1" + std::string(half, '0') + std::string(half - 1, '1');
            return std::stoi(res);
        }
        long long cur = n;
        while (true) {
            std::string sc = std::to_string(cur);
            if ((int)sc.size() > len) {
                int half = sc.size() / 2;
                std::string res = "1" + std::string(half, '0') + std::string(half - 1, '1');
                return std::stoi(res);
            }
            int evens = 0, odds = 0;
            for (char c : sc) {
                if ((c - '0') % 2 == 0) evens++;
                else odds++;
            }
            if (evens == odds) return cur;
            cur++;
        }
    }
};

class Solution {
    public int closestFair(int n) {
        String s = String.valueOf(n);
        int len = s.length();
        if (len % 2 == 1) {
            int half = (len + 1) / 2;
            String res = "1" + "0".repeat(half) + "1".repeat(half - 1);
            return Integer.parseInt(res);
        }
        long cur = n;
        while (true) {
            String sc = String.valueOf(cur);
            if (sc.length() > len) {
                int half = sc.length() / 2;
                String res = "1" + "0".repeat(half) + "1".repeat(half - 1);
                return Integer.parseInt(res);
            }
            int evens = 0, odds = 0;
            for (int i = 0; i < sc.length(); i++) {
                if ((sc.charAt(i) - '0') % 2 == 0) evens++;
                else odds++;
            }
            if (evens == odds) return (int) cur;
            cur++;
        }
    }
}

